--- /dev/null
+++ b/tests/proxy-partners.test.ts
@@ -0,0 +1,53 @@
+import { beforeAll, describe, expect, it } from "vitest";
+import { NextRequest } from "next/server";
+import { proxy } from "../proxy";
+import { CLIENT_COOKIE } from "../lib/client-auth-edge";
+
+// /partners sits behind the same check as the /client portal: a signed
+// sol_client session cookie, whose password was verified against the per-client
+// repo config at sign-in (lib/client-auth.ts). No session -> /client/login.
+
+const SECRET = "test-only-session-secret-not-used-in-prod-0123456789";
+
+async function mint(method: string, extra: Record<string, unknown> = {}): Promise<string> {
+  const payload = btoa(JSON.stringify({ method, issuedAt: Date.now(), ...extra }));
+  const key = await crypto.subtle.importKey(
+    "raw",
+    new TextEncoder().encode(SECRET),
+    { name: "HMAC", hash: "SHA-256" },
+    false,
+    ["sign"],
+  );
+  const mac = new Uint8Array(
+    await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(payload)),
+  );
+  return `${payload}.${Array.from(mac, (b) => b.toString(16).padStart(2, "0")).join("")}`;
+}
+
+function reqFor(url: string, cookieName?: string, cookieValue?: string): NextRequest {
+  const headers = new Headers();
+  if (cookieName && cookieValue) headers.set("cookie", `${cookieName}=${cookieValue}`);
+  return new NextRequest(url, { headers });
+}
+
+const deniedToClientLogin = (res: Response) =>
+  (res.headers.get("location") || "").includes("/client/login");
+
+beforeAll(() => {
+  process.env.SESSION_SECRET = SECRET;
+});
+
+describe("proxy() gate on /partners", () => {
+  it("anonymous request to /partners is denied", async () => {
+    const res = await proxy(reqFor("https://solaisoft.com/partners"));
+    expect(deniedToClientLogin(res)).toBe(true);
+  });
+
+  // Positive control: without it, a gate that redirected everything would pass.
+  it("a valid CLIENT session opens /partners", async () => {
+    const cookie = await mint("client", { slug: "station-street-fitness" });
+    const res = await proxy(reqFor("https://solaisoft.com/partners", CLIENT_COOKIE, cookie));
+    expect(deniedToClientLogin(res)).toBe(false);
+    expect(res.status).toBe(200);
+  });
+});
